export const getRefreshIntegrationUrl = () => {




  return `/api/integrations/refresh`
}

/**
 * No external CRM call. Updates the connection's lastSyncAt, bumps syncedAt on that source's canonical rows, and appends a crm_sync_events row.
 * @summary Mock "Refresh from source" — bumps syncedAt/lastSyncAt and writes a sync event
 */
export const refreshIntegration = async (refreshIntegrationInput: RefreshIntegrationInput, options?: RequestInit): Promise<IntegrationConnectionCard> => {

  return customFetch<IntegrationConnectionCard>(getRefreshIntegrationUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      refreshIntegrationInput,)
  }
);}




